+void addDockerBuildContextTask(DockerBase base, Architecture architecture = null, boolean local = false) {
+  String taskNameInfix = ''
+  String archiveSuffix = ''
+  String binDirectory = 'bin'
+
+  if (base == DockerBase.IRON_BANK) {
+    taskNameInfix = "Ironbank"
