+    with dockerBuildContext(architecture, base, local)
+
+    into(binDirectory) {
+      from configurations.transformLog4jJar
+    }
+  }
+}
+
+addDockerBuildContextTask(DockerBase.CENTOS)
+addDockerBuildContextTask(DockerBase.IRON_BANK, Architecture.X64, true) // Iron Bank builds are always local
+addDockerBuildContextTask(DockerBase.UBI)
