+      archiveClassifier = "docker-build-context"
+      archiveBaseName = "elasticsearch${archiveSuffix}"
+      with dockerBuildContext(architecture, base, true)
+
+      into (binDirectory) {
+        from configurations.transformLog4jJar
+      }
+    }
+
+  tasks.named("assemble").configure {
+    dependsOn(buildContextTask)
+  }
+
+  final TaskProvider<Copy> extractTask =
+    tasks.register(taskName('extract', architecture, base, 'DockerContext'), Copy) {
+      String archiveName = "elasticsearch${archiveSuffix}-${VersionProperties.elasticsearch}-docker-build-context"
+
+      from(tarTree("${project.buildDir}/distributions/${archiveName}.tar.gz")) {
+        eachFile { FileCopyDetails details ->
+          if (details.name.equals("Dockerfile")) {
+            filter ReplaceRemoteUrlWithLocalFilter
+          }
+        }
+      }
+      into "${project.buildDir}/docker/${archiveName}"
+
+      from Architecture.current() == Architecture.AARCH64 ? configurations.aarch64DockerSource : configurations.dockerSource
+
+      if (base == DockerBase.IRON_BANK) {
+        from (configurations.tini) {
+          rename { _ -> 'tini' }
+        }
+      }
+
+      dependsOn(buildContextTask)
+    }
+
+  tasks.register(taskName('build', architecture, base, 'DockerImageFromContext'), DockerBuildTask) {
+    dependsOn(extractTask)
+    dockerContext.fileProvider(extractTask.map { it.destinationDir })
+
+    if (base == DockerBase.UBI) {
+      baseImages = [base.getImage()]
+      tags = ['elasticsearch-ubi-from-context:test']
+    } else if (base == DockerBase.IRON_BANK) {
+      Map<String, String> buildArgsMap = [
+        'BASE_REGISTRY': 'docker.elastic.co',
+        'BASE_IMAGE': 'ubi8/ubi',
+        'BASE_TAG': 'latest'
+      ]
+
+      String baseImage = base.getImage()
+      for (String key : buildArgsMap.keySet()) {
+        baseImage = baseImage.replace('${' + key + '}', buildArgsMap.get(key))
+      }
+
+      baseImages = [baseImage]
+      buildArgs = buildArgsMap
+      tags = ['elasticsearch-ironbank-from-context:test']
+    } else {
+      baseImages = [base.getImage(), 'alpine:latest']
+      tags = ['elasticsearch-from-context:test']
+    }
+  }
+}
+
 for (final Architecture architecture : Architecture.values()) {
