+    @Override
+    public int read() throws IOException {
+        ensureOpen();
+        while (true) {
+            try {
+                maybeOpenInputStream();
+                int bytesRead = delegate.read();
+                if (bytesRead == -1) {
+                    eof = true;
+                    return -1;
+                }
+                totalBytesRead += bytesRead;
+                return bytesRead;
+            } catch (IOException e) {
+                maybeThrow(e);
+            }
+        }
+    }
+
+    @Override
+    public int read(byte[] b, int off, int len) throws IOException {
+        ensureOpen();
+        while (true) {
+            try {
+                maybeOpenInputStream();
+                int bytesRead = delegate.read(b, off, len);
+                if (bytesRead == -1) {
+                    eof = true;
+                    return -1;
+                }
+                totalBytesRead += bytesRead;
+                return bytesRead;
+            } catch (IOException e) {
+                maybeThrow(e);
+            }
+        }
