+            try {
+                retrieveAndUpdateDatabase(name, metadata);
+            } catch (Exception e) {
+                LOGGER.error((Supplier<?>) () -> new ParameterizedMessage("attempt to download database [{}] failed", name), e);
+            }
+        });
